BEGIN;
-- Test sessions are MFA-verified (aal2) unless a test clears this; admin authority requires it.
SELECT pg_catalog.set_config('request.jwt.claim', '{"aal":"aal2"}', true);
SELECT no_plan();
INSERT INTO auth.users(id,aud,role,email,raw_user_meta_data,created_at,updated_at) VALUES
('e1300000-0000-4000-8000-000000000001','authenticated','authenticated','progress-admin@example.test','{}',now(),now()),
('e1300000-0000-4000-8000-000000000002','authenticated','authenticated','progress-owner@example.test','{}',now(),now()),
('e1300000-0000-4000-8000-000000000003','authenticated','authenticated','progress-other@example.test','{}',now(),now());
INSERT INTO public.user_roles(user_id,role,granted_by) VALUES('e1300000-0000-4000-8000-000000000001','admin','e1300000-0000-4000-8000-000000000001');
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claim.sub','e1300000-0000-4000-8000-000000000001',true);
SELECT set_config('pgtap.course',public.admin_create_course('progress-security-test')::text,true);
SELECT public.admin_upsert_course_translation(current_setting('pgtap.course')::uuid,'en','Progress test','Test');
SELECT public.admin_set_translation_publication(current_setting('pgtap.course')::uuid,'en',true);
SELECT public.admin_set_course_status(current_setting('pgtap.course')::uuid,'published');
SELECT set_config('pgtap.module',public.admin_create_course_module(current_setting('pgtap.course')::uuid)::text,true);
SELECT public.admin_save_module_translation(current_setting('pgtap.module')::uuid,'en','Module');
SELECT public.admin_set_module_translation_publication(current_setting('pgtap.module')::uuid,'en',true);
SELECT set_config('pgtap.lesson',public.admin_create_lesson(current_setting('pgtap.module')::uuid,'video')::text,true);
SELECT public.admin_save_lesson_translation(current_setting('pgtap.lesson')::uuid,'en','Video');
SELECT public.admin_set_lesson_translation_publication(current_setting('pgtap.lesson')::uuid,'en',true);
SELECT public.admin_set_lesson_status(current_setting('pgtap.lesson')::uuid,'published');
SELECT set_config('pgtap.video',public.mux_begin_lesson_upload(current_setting('pgtap.lesson')::uuid)::text,true);
SELECT public.mux_attach_upload(current_setting('pgtap.video')::uuid,'upload_progress_test');
RESET ROLE;
SET LOCAL ROLE service_role;
SELECT public.mux_process_webhook('evt_progress_ready','video.asset.ready',jsonb_build_object('id','asset_progress_test','upload_id','upload_progress_test','passthrough',current_setting('pgtap.video'),'playback_ids',jsonb_build_array(jsonb_build_object('id','playback_progress_test','policy','signed')),'duration',100));
RESET ROLE;
SELECT ok(NOT has_table_privilege('authenticated','public.video_progress','UPDATE'),'direct video progress writes denied');
SELECT ok(NOT has_table_privilege('authenticated','public.lesson_progress','INSERT'),'direct lesson completion writes denied');
SELECT ok(NOT has_schema_privilege('authenticated','learning_private','USAGE'),'sessions and watched intervals are private');
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claim.sub','e1300000-0000-4000-8000-000000000002',true);
SELECT throws_ok($$SELECT * FROM public.learner_start_video_session(current_setting('pgtap.lesson')::uuid,'en')$$,'42501',NULL,'unenrolled learner denied');
SELECT set_config('pgtap.enrollment',public.learner_grant_free_enrollment(current_setting('pgtap.course')::uuid)::text,true);
SELECT set_config('pgtap.session',(SELECT session_id::text FROM public.learner_start_video_session(current_setting('pgtap.lesson')::uuid,'en')),true);
SELECT is((SELECT percent FROM public.learner_checkpoint_video(current_setting('pgtap.session')::uuid,'en',1,0,true)),0,'play establishes a baseline');
RESET ROLE;
UPDATE learning_private.video_sessions SET last_at=clock_timestamp()-interval '5 seconds' WHERE id=current_setting('pgtap.session')::uuid;
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claim.sub','e1300000-0000-4000-8000-000000000002',true);
SELECT is((SELECT watched_seconds FROM public.learner_checkpoint_video(current_setting('pgtap.session')::uuid,'en',2,5,true)),5,'plausible watched segment credited');
SELECT is((SELECT watched_seconds FROM public.learner_checkpoint_video(current_setting('pgtap.session')::uuid,'en',2,90,true)),5,'duplicate sequence does not earn credit');
SELECT is((SELECT position_seconds FROM public.learner_checkpoint_video(current_setting('pgtap.session')::uuid,'en',1,0,true)),5::numeric,'out of order checkpoint cannot regress resume');
SELECT is((SELECT watched_seconds FROM public.learner_checkpoint_video(current_setting('pgtap.session')::uuid,'en',3,99,true)),5,'seek to end grants no watched credit');
SELECT throws_ok($$SELECT * FROM public.learner_checkpoint_video(current_setting('pgtap.session')::uuid,'en',4,101,true)$$,'22023',NULL,'out of bounds position denied');
SELECT throws_ok($$SELECT * FROM public.learner_checkpoint_video(current_setting('pgtap.session')::uuid,'en',4,'NaN',true)$$,'22023',NULL,'nonfinite position denied');
SELECT is((SELECT completed FROM public.learner_checkpoint_video(current_setting('pgtap.session')::uuid,'en',4,0,false)),false,'seeking does not complete lesson');
SELECT * FROM public.learner_checkpoint_video(current_setting('pgtap.session')::uuid,'en',5,0,true);
RESET ROLE;
UPDATE learning_private.video_sessions SET last_at=clock_timestamp()-interval '5 seconds' WHERE id=current_setting('pgtap.session')::uuid;
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claim.sub','e1300000-0000-4000-8000-000000000002',true);
SELECT is((SELECT watched_seconds FROM public.learner_checkpoint_video(current_setting('pgtap.session')::uuid,'en',6,5,true)),5,'replayed timeline is not counted twice');
SELECT set_config('pgtap.session2',(SELECT session_id::text FROM public.learner_start_video_session(current_setting('pgtap.lesson')::uuid,'en')),true);
SELECT throws_ok($$SELECT * FROM public.learner_checkpoint_video(current_setting('pgtap.session')::uuid,'en',7,10,true)$$,'42501',NULL,'new tab supersedes prior session');
SELECT is((SELECT position_seconds FROM public.video_progress WHERE enrollment_id=current_setting('pgtap.enrollment')::uuid),5::numeric,'resume saved in database');
SELECT set_config('request.jwt.claim.sub','e1300000-0000-4000-8000-000000000003',true);
SELECT is((SELECT count(*)::integer FROM public.video_progress),0,'cross user cannot read progress');
SELECT throws_ok($$SELECT * FROM public.learner_checkpoint_video(current_setting('pgtap.session2')::uuid,'en',1,10,true)$$,'42501',NULL,'cross user cannot checkpoint');
SELECT throws_ok($$SELECT * FROM public.mux_get_video_management(current_setting('pgtap.lesson')::uuid)$$,'42501',NULL,'learner cannot read management metadata');
SELECT is((SELECT count(*)::integer FROM public.mux_list_manageable_lessons('en')),0,'learner cannot list upload targets');
RESET ROLE;
-- Seed only private timing/interval state as test operator to test 90% boundary quickly.
UPDATE learning_private.watched_intervals SET intervals='{[0,89)}' WHERE enrollment_id=current_setting('pgtap.enrollment')::uuid;
UPDATE learning_private.video_sessions SET last_position=89,last_at=clock_timestamp()-interval '1 second',was_playing=true WHERE id=current_setting('pgtap.session2')::uuid;
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claim.sub','e1300000-0000-4000-8000-000000000002',true);
SELECT is((SELECT completed FROM public.learner_checkpoint_video(current_setting('pgtap.session2')::uuid,'en',1,89,true)),false,'89% is not complete');
RESET ROLE;
UPDATE learning_private.video_sessions SET last_at=clock_timestamp()-interval '1 second' WHERE id=current_setting('pgtap.session2')::uuid;
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claim.sub','e1300000-0000-4000-8000-000000000002',true);
SELECT is((SELECT completed FROM public.learner_checkpoint_video(current_setting('pgtap.session2')::uuid,'en',2,90,true)),true,'90% unique timeline completes lesson');
SELECT is((SELECT status FROM public.lesson_progress WHERE lesson_id=current_setting('pgtap.lesson')::uuid),'completed','lesson completion is server controlled');
RESET ROLE;
UPDATE public.enrollments SET status='completed',completed_at=now() WHERE id=current_setting('pgtap.enrollment')::uuid;
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claim.sub','e1300000-0000-4000-8000-000000000002',true);
SELECT is((SELECT count(*)::integer FROM public.mux_get_lesson_playback(current_setting('pgtap.lesson')::uuid,'en')),1,'completed enrollment retains playback');
RESET ROLE;
UPDATE public.enrollments SET status='revoked',revoked_at=now(),revoked_by='e1300000-0000-4000-8000-000000000001' WHERE id=current_setting('pgtap.enrollment')::uuid;
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claim.sub','e1300000-0000-4000-8000-000000000002',true);
SELECT throws_ok($$SELECT * FROM public.learner_checkpoint_video(current_setting('pgtap.session2')::uuid,'en',3,95,true)$$,'42501',NULL,'revoked enrollment cannot save more progress');
SELECT throws_ok($$SELECT public.admin_grant_course_access('progress-owner@example.test','progress-security-test','development_test')$$,'42501',NULL,'learner cannot grant course access');
RESET ROLE;
UPDATE public.courses SET price_minor=49900 WHERE id=current_setting('pgtap.course')::uuid;
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claim.sub','e1300000-0000-4000-8000-000000000001',true);
SELECT set_config('pgtap.admin_enrollment',public.admin_grant_course_access('progress-owner@example.test','progress-security-test','development_test')::text,true);
SELECT is(public.admin_grant_course_access('progress-owner@example.test','progress-security-test','development_test'),current_setting('pgtap.admin_enrollment')::uuid,'admin grant is idempotent');
SELECT throws_ok($$SELECT public.admin_grant_course_access('progress-owner@example.test','progress-security-test','unapproved')$$,'22023',NULL,'grant reason must be approved');
RESET ROLE;
SELECT is((SELECT grant_source FROM public.enrollments WHERE id=current_setting('pgtap.admin_enrollment')::uuid),'admin','manual grant is distinct from free enrollment');
SELECT is((SELECT price_minor FROM public.courses WHERE id=current_setting('pgtap.course')::uuid),49900::bigint,'manual grant does not change price');
SELECT is((SELECT count(*)::integer FROM public.admin_audit_log WHERE enrollment_id=current_setting('pgtap.admin_enrollment')::uuid AND action='enrollment.granted'),1,'exactly one audit record for repeated grant');
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claim.sub','e1300000-0000-4000-8000-000000000002',true);
SELECT is((SELECT count(*)::integer FROM public.mux_get_lesson_playback(current_setting('pgtap.lesson')::uuid,'en')),1,'administrator grant unlocks protected playback');
SELECT set_config('request.jwt.claim.sub','e1300000-0000-4000-8000-000000000003',true);
SELECT throws_ok($$SELECT public.learner_grant_free_enrollment(current_setting('pgtap.course')::uuid)$$,'P0002',NULL,'paid course still rejects learner free enrollment');
RESET ROLE;
SELECT * FROM finish();
ROLLBACK;
